float sdCircle( vec2 p, float r )
{
    return length(p) -r;
}
float sdFace( vec2 p, float r )
{
    if (p.y < -0.43)
    {
        p.y+=0.09*cos(20./mod(p.y,1.4));
    }

    return sdCircle(p, r);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
	float d1 = sdFace(p,0.9);
    vec3 col = vec3(0.1);
    col = (d1<0.0) ? vec3(0.9,0.6,0.3) : vec3(1.0);
    col *= exp(0.9*abs(d1));
    if ( p.y < -0.43 )
        col *= vec3(0.65,0.85,1.0);
    col = mix( col, vec3(1.0,0.7,0.4), 1.0-smoothstep(0.0,0.01,abs(d1)) );

    // Output to screen
    fragColor = vec4(col,1.0);
}
